    int n = N * 101 + 2;
    vector<vector<int>> g(n);
    vector<Edge> edges;
    auto add_edge = [&](int from, int to, int cap, int cost) {
        g[from].push_back((int)edges.size());
        edges.push_back({to, -1, cap, cost});
        g[to].push_back((int)edges.size());
        edges.push_back({from, -1, 0, -cost});
        edges[edges.size()-2].rev = edges.size()-1;
        edges[edges.size()-1].rev = edges.size()-2;
    };
    for (int i = 0; i < k; i++) {
        int x;
        scanf("%d", &x);
        x--;
        add_edge(n-2, x*101, 1, 0);
    }
    for (int i = 0; i < 101; i++) {
        add_edge(i, n-1, INF, i*c);
    }
    for (int i = 1; i < N; i++) {
        for (int j = 0; j+1 < 101; j++) {
            add_edge(i*101 + j, i*101 + j + 1, INF, 0);
        }
    }
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        for (int j = 0; j+1 < 101; j++) {
