    int s = n-2, t = n-1;
    int flow = 0, cost = 0;
    while (flow < k) {
        vector<int> dist(n, INF);
        vector<int> prevv(n, -1);
        vector<int> preve(n, -1);
        vector<int> inq(n, 0);
        queue<int> q;
        dist[s] = 0;
        q.push(s);
        inq[s] = 1;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            inq[v] = 0;
            for (int ei : g[v]) {
                Edge& e = edges[ei];
                if (e.cap > 0 && dist[v] + e.cost < dist[e.to]) {
                    dist[e.to] = dist[v] + e.cost;
                    prevv[e.to] = v;
                    preve[e.to] = ei;
                    if (!inq[e.to]) {
                        q.push(e.to);
                        inq[e.to] = 1;
                    }
                }
            }
        }
        if (dist[t] == INF) break;
        int addflow = k - flow;
        for (int v = t; v != s; v = prevv[v]) {
            int ei = preve[v];
            addflow = min(addflow, edges[ei].cap);
        }
        for (int v = t; v != s; v = prevv[v]) {
            int ei = preve[v];
            Edge& e = edges[ei];
            e.cap -= addflow;
            edges[e.rev].cap += addflow;
            cost += e.cost * addflow;
        }
        flow += addflow;
    }
    assert(flow == k);
    printf("%d\n", cost);
    return 0;
}
